import{_ as t,l as i,o as a,c as l,v as s,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"零拷贝网络","description":"","frontmatter":{"title":"零拷贝网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zero-copy-network.md","filePath":"cs/zero-copy-network.md","lastUpdated":1789023840000}'),_={name:"cs/zero-copy-network.md"};function m(E,e,f,h,u,A){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=s('<h1 id="零拷贝网络" tabindex="-1">零拷贝网络 <a class="header-anchor" href="#零拷贝网络" aria-label="Permalink to &quot;零拷贝网络&quot;">​</a></h1><div class="epigraph"><p>零拷贝让包数据只被 DMA 一次：MSG_ZEROCOPY、sendfile、AF_XDP umem 或包头仅线性拷贝，负载留在页上。</p><footer>—— 据 Linux MSG_ZEROCOPY 文档；sendfile 实践；AF_XDP 对 umem 的说明</footer></div><p><a href="/cs/sendfile-splice">sendfile</a> 已从文件侧减拷。<a href="/cs/skbuff">sk_buff</a> 的 frags 是载体。<a href="/cs/rss-multiqueue">RSS</a> 解决 CPU。缺口是 <strong>网络零拷贝</strong> 的几条路径与完成通知——不是绝对零。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>send</code> 默认拷进 skb 线性区或内核页。<code>MSG_ZEROCOPY</code>：用户页钉住，协议用，完成用错误队列通知可改页。接收：<code>recvmmsg</code> 仍常拷；真正少拷是 mmap 包环、AF_XDP、或 GRO 后直接 splice 到文件。缺口：页必须对齐、不能立即重写；校验卸载与加密可能迫使拷贝。本课不把 TLS 内核卸载细节写完。</p><p><span class="marginnote">「零拷贝」统计上常是「少一次」。调试要用完成通知，否则数据竞争。与 O_DIRECT 同构：应用承担生命周期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送静态文件：sendfile。发送用户缓冲：MSG_ZEROCOPY + 等 completion。接收旁路：AF_XDP 把 umem 填给驱动。对照 DPDK：全程用户 mbuf。对照 <a href="/cs/fs-mmap-coherence">mmap 文件</a>：文件零拷贝与网络零拷贝可在 sendfile 汇合。</p>',8)),(a(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E9%A1%B5%E6%88%96%E6%96%87%E4%BB%B6%E9%A1%B5%22%5D%20--%3E%20PIN%5B%22%E9%92%89%E9%A1%B5%22%5D%0A%20%20PIN%20--%3E%20DMA%5B%22%E7%BD%91%E5%8D%A1%20DMA%22%5D%0A%20%20CMP%5B%22%E5%AE%8C%E6%88%90%E9%80%9A%E7%9F%A5%22%5D%20--%3E%20UNPIN%5B%22%E6%89%8D%E5%8F%AF%E6%94%B9%E9%A1%B5%22%5D%0A%20%20COPY%5B%22%E6%99%AE%E9%80%9A%20send%22%5D%20--%3E%20SKB%5B%22%E5%86%85%E6%A0%B8%E6%8B%B7%E8%B4%9D%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>零拷贝把 CPU memcpy 从数据面拿掉，瓶颈回到 DMA 与协议状态。它不取消 <a href="/cs/socket-buffers">套接字缓冲</a> 的会计——记账仍按字节。不要写成网卡广告。与 XDP：XDP 改的是早处理，数据仍可在同一页上 TX。</p><p>失败回退到拷贝必须正确，否则静默损坏。</p><p>实现上：MSG_ZEROCOPY 的完成通知走错误队列，应用必须读，否则不能重用缓冲。页必须 page-aligned 且生命周期覆盖 DMA。校验与加密卸载失败会静默拷贝。 读法上只引用<a href="/cs/rss-multiqueue">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>零拷贝网络</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 NIC 的 header-data split。不保证虚拟机 vhost 零拷贝与客户页的 IOMMU 映射总成功。下一课把「绕过 TCP 的传输」接到 OS：RDMA。</p><p>版本字段会变，课序钉的是机制对象「零拷贝网络」，不是某一主线内核的结构体名。 后课默认：发送路径可钉用户/文件页 DMA。RDMA 在 OS 中的队列对与内存注册，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>零拷贝靠钉页与 DMA，完成前不能改缓冲。</li><li>sendfile、MSG_ZEROCOPY、AF_XDP 是不同接头。</li><li>RDMA 是下一课。</li><li>出处：Linux <code>MSG_ZEROCOPY</code>；AF_XDP；sendfile。</li></ul>',11))])}const B=t(_,[["render",m]]);export{D as __pageData,B as default};
